const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');
const { Ticket } = require('../models/ticket');
const { ChatHistory } = require('../models/chat');

const server = http.createServer();
const io = new Server(server);

const pub = new Redis(process.env.REDIS_HOST);
const sub = pub.duplicate();
io.adapter(createAdapter(pub, sub));

const ticketNsp = io.of(/^\/support\/ticket-[a-z0-9-]+$/);

ticketNsp.use(async (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('Authentication required'));

  try {
    const user = jwt.verify(token, process.env.JWT_SECRET);
    const ticketId = socket.nsp.name.replace('/support/ticket-', '');

    const ticket = await Ticket.findById(ticketId);
    if (!ticket) return next(new Error('Ticket not found'));

    // Check if user is either the customer who filed the ticket or assigned support staff
    if (ticket.customerId !== user.userId && user.role !== 'SUPPORT_AGENT') {
      return next(new Error('Access denied: unauthorized to join ticket namespace'));
    }

    socket.user = user;
    next();
  } catch {
    next(new Error('Authentication failed'));
  }
});

ticketNsp.on('connection', async (socket) => {
  const ticketId = socket.nsp.name.replace('/support/ticket-', '');

  const messages = await ChatHistory.find({ ticketId }).sort({ createdAt: 1 });
  socket.emit('ticket_history', messages);

  socket.on('client_message', async (msg) => {
    const saved = await ChatHistory.create({
      ticketId,
      content: msg.text,
      sender: socket.user.userId
    });
    socket.nsp.emit('new_message', saved);
  });
});

server.listen(4005);
